using UnityEngine;
using UnityEditor;
public sealed class EquipmentItemsEditor:EditorWindow {
 Vector2 scroll;int selected;
 [MenuItem("Editor/Objetos equipables",false,2002)] public static void Open(){GetWindow<EquipmentItemsEditor>("Objetos equipables").Show();}
 void OnGUI(){minSize=new Vector2(540,520);var asset=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");if(asset==null)return;EditorGUILayout.LabelField("CATÁLOGO DE OBJETOS EQUIPABLES",EditorStyles.boldLabel);EditorGUILayout.HelpBox("Aquí creas objetos y asignas su icono (imagen/Texture2D), ranura y bonos. Personaje tiene tres ranuras; puedes crear varias opciones para cada una. Tus objetos existentes se conservan.",MessageType.Info);var s=new SerializedObject(asset);s.Update();var list=s.FindProperty("equipment");if(list.arraySize>0){string[] names=new string[list.arraySize];for(int i=0;i<names.Length;i++)names[i]=list.GetArrayElementAtIndex(i).FindPropertyRelative("name").stringValue;selected=Mathf.Clamp(selected,0,names.Length-1);selected=EditorGUILayout.Popup("Objeto",selected,names);scroll=EditorGUILayout.BeginScrollView(scroll);var e=list.GetArrayElementAtIndex(selected);using(new EditorGUI.DisabledScope(true))EditorGUILayout.PropertyField(e.FindPropertyRelative("id"),new GUIContent("ID estable"));EditorGUILayout.PropertyField(e.FindPropertyRelative("specialEffectIds"),new GUIContent("Efectos futuros (IDs)"),true);EditorGUILayout.PropertyField(e.FindPropertyRelative("name"),new GUIContent("Nombre"));var slot=e.FindPropertyRelative("slot");int index=asset.equipment[selected].SlotIndex;int next=EditorGUILayout.Popup("Ranura",index,new[]{"1","2","3"});if(next!=index)slot.stringValue=(next+1).ToString();EditorGUILayout.PropertyField(e.FindPropertyRelative("description"),new GUIContent("Descripción"));EditorGUILayout.PropertyField(e.FindPropertyRelative("icon"),new GUIContent("Icono"));var icon=e.FindPropertyRelative("icon").objectReferenceValue as Texture2D;if(icon!=null){Rect preview=GUILayoutUtility.GetRect(100,100);GUI.DrawTexture(preview,icon,ScaleMode.ScaleToFit,true);}foreach(string key in new[]{"health","strength","defense","luck"})EditorGUILayout.PropertyField(e.FindPropertyRelative(key),new GUIContent(key=="health"?"Vida +":key=="strength"?"Fuerza +":key=="defense"?"Defensa +":"Suerte +"));EditorGUILayout.EndScrollView();}s.ApplyModifiedProperties();if(GUILayout.Button("Crear objeto")){Undo.RecordObject(asset,"Crear objeto equipable");var values=new System.Collections.Generic.List<PlayerEquipment>(asset.equipment);values.Add(new PlayerEquipment("Nuevo objeto","1",0,0,0,0));asset.equipment=values.ToArray();EditorUtility.SetDirty(asset);selected=asset.equipment.Length-1;}if(GUILayout.Button("Guardar objetos"))AssetDatabase.SaveAssets();}
}
